  "Добавляйся ко мне в NEBO, будем смотреть, какой у нас день и насколько мы совпадаем:": "Add me on NEBO, we’ll see what kind of day we have and how well we match:",
  "Добавь близких, покажем, что вас связывает, и напомним о днях рождения.": "Add people close to you, we’ll show what connects you and remind you of birthdays.",
  "Добавь время и город": "Add the time and city",
