  "Добавь карты близких в «Мои карты», и здесь появятся ваши пары.": "Add the charts of people close to you to “My charts” and your pairs will appear here.",
  "Добро пожаловать в Plus": "Welcome to Plus",
  "Доброе утро,": "Good morning,",
  "Дождь": "Rain",
  "Дождь, море, истории": "Rain, sea, stories",
  "Долго приходилось терпеть то, что давно не подходит: нагрузку, условия, людей. Зато теперь понятно, что для тебя важно на самом деле.": "For a long time you had to put up with what stopped suiting you: the load, the conditions, the people. But now it is clear what really matters to you.",
