  "Дыхание 3 минуты": "Breathing, 3 minutes",
  "Дыхание на 2 минуты": "Breathing for 2 minutes",
  "Дыхание помогает в моменте, а привычки снижают общий фон стресса. Когда выспался, поел и подвигался, срывов меньше. Берём только то, что делается за минуту или две.": "Breathing helps in the moment, and habits lower the overall level of stress. When you have slept, eaten and moved, there are fewer breakdowns. We only take what can be done in a minute or two.",
  "Дыхание, пузыри и минута тишины": "Breathing, bubbles and a minute of quiet",
  "Дыхание, расслабление тела, звуки": "Breathing, body relaxation, sounds",
  "Дыхание, тело, звуки": "Breathing, body, sounds",
  "Дыханием можно управлять руками, а пульсом нет. Когда выдох длиннее вдоха, пульс замедляется, и телу приходит сигнал, что опасности нет. Эффект чувствуется за 1–2 минуты.": "You can control breathing by hand, but not your pulse. When the exhale is longer than the inhale, the pulse slows and the body gets the signal that there is no danger. You feel the effect in 1–2 minutes.",
  "Если NEBO долго загружается, попробуй отключить VPN.": "If NEBO takes a long time to load, try turning off your VPN.",
  "Если email свободен, шестизначный код отправлен. Если аккаунт уже существует, войди или восстанови пароль: профили автоматически не объединяются.": "If the email is free, a six-digit code has been sent. If the account already exists, sign in or restore your password: profiles are not merged automatically.",
  "Если включён VPN, выключи его и попробуй ещё раз. Иногда VPN мешает приложению подключиться.": "If a VPN is on, turn it off and try again. A VPN sometimes keeps the app from connecting.",
  "Если дело не ждёт, выбирай день без отметки «лучше не стоит» и перепроверяй детали.": "If it can’t wait, choose a day without the “better not” mark and double-check the details.",
  "Если есть травма или боль в какой-то мышце, пропусти её или напрягай совсем слегка.": "If you have an injury or pain in a muscle, skip it or tense it very lightly.",
  "Если кружится голова, дыши обычно и сделай паузу.": "If you feel dizzy, breathe normally and take a pause.",
  "Если такой аккаунт существует, код уже отправлен на email.": "If such an account exists, the code has already been sent by email.",
