  "Нужны имя, дата и город рождения. Время, если знаешь.": "You need a name, date and city of birth. Time, if you know it.",
  "О чём лучше сказать сразу": "What is better said right away",
  "ОКТ": "OCT",
  "Оба живут чувствами и заботой. Тепло вместе, важно только не утонуть в эмоциях вдвоём.": "Both live by feelings and care. It is warm together, just don’t drown in emotions as a pair.",
  "Оба надёжные и практичные. Вместе хорошо строить планы, дом и общее дело.": "Both are reliable and practical. It is good to build plans, a home and a shared project together.",
  "Оба ценят свободу и своё мнение. Интересно вместе, если не давить друг на друга.": "Both value freedom and their own opinion. It is interesting together if you don’t press each other.",
  "Обнови резюме и скажи знакомым, что открыт к предложениям. Решение принимай, когда предложение будет на руках, а не заранее.": "Update your CV and tell people you are open to offers. Decide when you have an offer in hand, not before.",
  "Обновить": "Update",
  "Обратная связь": "Feedback",
  "Объект в небе → точка на карте": "An object in the sky → a point on the chart",
  "Обычный вопрос, понятный ответ. Ниже пример того, как можно читать свою карту.": "A normal question, a clear answer. Below is an example of how you can read your chart.",
  "Обычный день, без особых советов": "An ordinary day, no special advice",
  "Обычный день, без резких поворотов": "An ordinary day, no sharp turns",
