  "Овне": "Aries",
  "Огонь": "Fire",
  "Один думает, другой чувствует. Интересно вместе, но сказанное не всегда понимается одинаково.": "One thinks, the other feels. It is interesting together, but what is said is not always understood the same way.",
  "Один из двенадцати участков круга. Здесь видно, какие точки твоей карты в нём стоят.": "One of the twelve parts of the circle. Here you can see which points of your chart stand in it.",
  "Один ищет свободу, другой порядок. Получается, если договориться о правилах.": "One seeks freedom, the other order. It works if you agree on the rules.",
  "Один расклад в неделю бесплатно. В Plus расклады без ограничений.": "One spread a week is free. In Plus spreads are unlimited.",
  "Один расклад в неделю бесплатный, и на этой неделе он уже твой. Можно открыть ещё один расклад или все сразу с NEBO Plus.": "One spread a week is free, and this week’s is already yours. You can open another spread or all of them at once with NEBO Plus.",
  "Один расклад за 99 ₽": "One spread for 99 ₽",
  "Один строит, другой согревает. Хорошо для дома и семьи, если ценить вклад друг друга.": "One builds, the other warms. Good for home and family if you value each other’s part.",
  "Одна карта для быстрого ответа, три для ситуации.": "One card for a quick answer, three for a situation.",
  "Одна карта и совет на сегодня": "One card and advice for today",
  "Одна руна и совет на сегодня": "One rune and advice for today",
  "Одно уведомление утром. В особые дни, например в твой день рождения или в полнолуние, может прийти ещё одно.": "One notification in the morning. On special days, such as your birthday or a full moon, one more may come.",
