  "Они нужны, чтобы точно посчитать твою натальную карту.": "They are needed to calculate your natal chart accurately.",
  "Оплата ещё обрабатывается в RuStore. Дождись результата или нажми «Восстановить покупку».": "The payment is still being processed in RuStore. Wait for the result or tap “Restore purchase”.",
  "Оплата ещё проверяется. Как только RuStore её подтвердит, покупка появится здесь сама.": "The payment is still being checked. As soon as RuStore confirms it, the purchase will appear here by itself.",
