  "По буквам имени считаются число души, образа и таланта. Это открывается с NEBO Plus или с «Эзотерикой на год».": "The soul, image and talent numbers are calculated from the letters of your name. This opens with NEBO Plus or “Esoterics for a year”.",
  "По возрастам: три этапа жизни": "By age: three stages of life",
  "По дням открыт ближайший месяц. Этот день войдёт в него ближе к дате, а пока смотри главное месяца ниже.": "The next month is open day by day. This day joins it closer to the date, for now see the month’s main points below.",
  "По китайскому гороскопу": "By the Chinese horoscope",
