  "Повторить": "Repeat",
  "Под стрессом мы незаметно зажимаем плечи, челюсть, живот. Если сначала сильно напрячь мышцу, а потом отпустить, она расслабляется глубже, чем от команды «расслабься». Заодно учишься замечать, где копится напряжение.": "Under stress we quietly clench our shoulders, jaw and stomach. If you first tense a muscle hard and then let go, it relaxes more deeply than from the command “relax”. You also learn to notice where tension builds up.",
