  "Результат будет, но не сразу. То, что начнётся этой осенью, принесёт плоды к весне.": "There will be a result, but not right away. What starts this autumn will bear fruit by spring.",
  "Ремонт": "Renovation",
  "Ретроградный Меркурий": "Mercury retrograde",
  "Ретроградный Меркурий: несколько недель кажется, что Меркурий идёт по небу назад. Меркурий отвечает за разговоры, переписку, договоры и поездки, поэтому в эти дни люди чаще путаются в словах, сроках и билетах.": "Mercury retrograde: for a few weeks Mercury seems to move backwards across the sky. Mercury is in charge of talks, messages, contracts and trips, so on these days people more often mix up words, deadlines and tickets.",
  "Ровная неделя без резких поворотов": "A steady week with no sharp turns",
  "Рост, удача, расширение горизонтов": "Growth, luck, wider horizons",
  "Руна": "Rune",
