  "Стрелец": "Sagittarius",
  "Стрельце": "Sagittarius",
  "Стресс бывает разный, и помогает разное. Если накрыло прямо сейчас, нажми красную кнопку. Если хочешь разобраться, выбери состояние. Если хочешь стать устойчивее, делай по 2–5 минут в день и веди дневник.": "Stress comes in different forms, and different things help. If it hits you right now, tap the red button. If you want to figure it out, choose a state. If you want to become steadier, do 2–5 minutes a day and keep a diary.",
  "Стресс кажется «просто плохим днём», пока не видишь его по дням. Отмечай уровень и причину за 10 секунд. Через неделю станет видно, что тебя выбивает и в какие дни, и под это можно подбирать технику.": "Stress seems like “just a bad day” until you see it by days. Mark the level and reason in 10 seconds. In a week you will see what throws you off and on which days, and you can pick a technique for it.",
