  "Точки": "Points",
  "Транзиты, прогрессии и возвращения используют разные правила расчёта. Это методы, а не готовые предсказания.": "Transits, progressions and returns use different calculation rules. These are methods, not ready-made predictions.",
  "Тревожный мозг живёт в «а вдруг» и «что будет». Когда ты ищешь глазами, ушами и руками реальные вещи вокруг, внимание возвращается в сейчас, и накрутка слабеет.": "An anxious brain lives in “what if” and “what will happen”. When you search for real things around you with your eyes, ears and hands, attention returns to now and the spiralling weakens.",
