  "Цифры твоей даты рождения разложены по клеткам. Чем больше одинаковых цифр, тем ярче эта черта. «Нет» значит, что здесь полагаться лучше на план, а не на удачу.": "The digits of your birth date are laid out in cells. The more identical digits, the stronger the trait. “None” means it is better to rely on a plan here, not on luck.",
