  "Числа": "Numbers",
  "Числа делятся на три семьи: 1, 5, 7 про свободу и ум, 2, 4, 8 про дело и порядок, 3, 6, 9 про чувства и заботу. Внутри семьи легко, а между семьями люди дополняют друг друга.": "Numbers fall into three families: 1, 5, 7 are about freedom and mind; 2, 4, 8 about work and order; 3, 6, 9 about feelings and care. Within a family it is easy, and between families people complement each other.",
  "Числа считаются по дате рождения и по имени. Без даты считать нечего.": "Numbers are calculated from your birth date and name. Without a date there is nothing to calculate.",
