  "Чтобы покупка не потерялась, сначала привяжи вход через Яндекс, VK или почту в профиле.": "So the purchase doesn’t get lost, first link Yandex, VK or email sign-in in your profile.",
  "Чтобы сравнить пару, укажи свою дату рождения в профиле.": "To compare a couple, enter your birth date in your profile.",
  "Чёрные": "Black",
  "Шаг {0} из {1}": "Step {0} of {1}",
  "Шестизначный код из письма": "The six-digit code from the email",
  "Эзотерика": "Esoterics",
  "Эзотерика открыта": "Esoterics is open",
  "Эклиптический круг делят на 12 равных знаков по 30°.": "The ecliptic circle is divided into 12 equal signs of 30°.",
  "Экран не открылся из-за ошибки. Мы уже получили отчёт. Попробуй перезагрузить приложение.": "The screen did not open because of an error. We have already received a report. Try reloading the app.",
  "Эмоции острее обычного": "Emotions are sharper than usual",
  "Эмоции, привычный отклик, то, что замечаешь только для себя": "Emotions, your usual reaction, what you notice only for yourself",
  "Это два конца одной оси карты, между ними всегда 180°. Так устроена любая карта, а о характере говорят сами эти точки и их связи с планетами.": "These are the two ends of one axis of the chart, always 180° apart. Every chart is built this way, and character is described by the points themselves and their links to planets.",
  "Это день {0}. {1}": "This is a day of {0}. {1}",
  "Это народные лунные традиции, а не наука. Для интереса и в помощь выбору, но не вместо врача, садовода или здравого смысла.": "These are folk lunar traditions, not science. For interest and to help you choose, not in place of a doctor, gardener or common sense.",
  "Это общие советы, не диета и не лечение.": "This is general advice, not a diet or treatment.",
  "Это пример расклада": "This is an example spread",
  "Это приёмы самопомощи, не лечение. Если тревога держится неделями или бывают приступы паники, обратись к врачу или психологу.": "These are self-help techniques, not treatment. If anxiety lasts for weeks or you have panic attacks, see a doctor or psychologist.",
  "Это продолжение того же рассказа, а не другой текст": "This continues the same story, it is not another text",
  "Это связь двух точек под углом {0}°. {1}": "This is a link between two points at an angle of {0}°. {1}",
  "Это связь двух точек под углом {0}°. {1}Смысл зависит от того, какие точки она соединяет.": "This is a link between two points at an angle of {0}°. {1}Its meaning depends on which points it connects.",
  "Это твой день": "This is your day",
  "Это три твоих личных числа: года, месяца и дня. Их считают по дате рождения и сегодняшней дате, поэтому они меняются. Каждое подсказывает, на что сейчас лучше потратить силы.": "These are your three personal numbers: of the year, month and day. They are calculated from your birth date and today’s date, so they change. Each one suggests where it is better to spend your energy now.",
  "Это ты в NEBO": "This is you in NEBO",
  "Этот аккаунт заблокирован. Войди в другой аккаунт или обратись в поддержку.": "This account is blocked. Sign in to another account or contact support.",
  "Этот код уже использовали все, кому он был выдан.": "This code has already been used by everyone it was issued to.",
  "Этот код уже использован.": "This code has already been used.",
