  "В старых книгах у каждой планеты был список из нескольких камней, и списки пересекались. Один камень на каждый месяц ювелиры утвердили только в 1912 году. Так что покупать кольцо по команде приложения не придётся.": "En los libros antiguos cada planeta tenía una lista de varias piedras, y las listas se solapaban. Los joyeros fijaron una piedra por mes solo en 1912. Así que no tendrás que comprarte un anillo porque lo diga una app.",
  "В твоей карте такого аспекта нет.": "En tu carta no hay ese aspecto.",
  "В чём я сильнее всего?": "¿En qué soy más fuerte?",
  "В этом доме у тебя нет планет: эта сфера живёт по правилам знака на его границе.": "No tienes planetas en esta casa: esta área se rige por el signo de su límite.",
