  "Год по китайскому календарю начинается в конце января или в феврале. Если день рождения в январе или начале февраля, животное считается по прошлому году. Это для интереса, а не для важных решений.": "El año del calendario chino empieza a finales de enero o en febrero. Si cumples años en enero o a principios de febrero, el animal se cuenta por el año anterior. Es por curiosidad, no para decisiones importantes.",
