  "Дыхание помогает в моменте, а привычки снижают общий фон стресса. Когда выспался, поел и подвигался, срывов меньше. Берём только то, что делается за минуту или две.": "La respiración ayuda en el momento y los hábitos bajan el nivel general de estrés. Si has dormido, comido y te has movido, hay menos crisis. Solo elegimos lo que se hace en un minuto o dos.",
  "Дыхание, пузыри и минута тишины": "Respiración, burbujas y un minuto de silencio",
  "Дыхание, расслабление тела, звуки": "Respiración, relajación del cuerpo, sonidos",
  "Дыхание, тело, звуки": "Respiración, cuerpo, sonidos",
  "Дыханием можно управлять руками, а пульсом нет. Когда выдох длиннее вдоха, пульс замедляется, и телу приходит сигнал, что опасности нет. Эффект чувствуется за 1–2 минуты.": "La respiración se puede controlar a voluntad; el pulso, no. Cuando la espiración es más larga que la inspiración, el pulso baja y el cuerpo recibe la señal de que no hay peligro. El efecto se nota en 1–2 minutos.",
  "Если NEBO долго загружается, попробуй отключить VPN.": "Si NEBO tarda mucho en cargar, prueba a desactivar la VPN.",
  "Если email свободен, шестизначный код отправлен. Если аккаунт уже существует, войди или восстанови пароль: профили автоматически не объединяются.": "Si el correo está libre, se ha enviado un código de seis dígitos. Si la cuenta ya existe, entra o recupera la contraseña: los perfiles no se unen automáticamente.",
  "Если включён VPN, выключи его и попробуй ещё раз. Иногда VPN мешает приложению подключиться.": "Si tienes VPN, apágala e inténtalo de nuevo. A veces la VPN impide que la app se conecte.",
  "Если дело не ждёт, выбирай день без отметки «лучше не стоит» и перепроверяй детали.": "Si no puede esperar, elige un día sin la marca «mejor no» y revisa bien los detalles.",
  "Если есть травма или боль в какой-то мышце, пропусти её или напрягай совсем слегка.": "Si tienes una lesión o dolor en algún músculo, sáltalo o ténsalo muy poco.",
  "Если кружится голова, дыши обычно и сделай паузу.": "Si te mareas, respira con normalidad y haz una pausa.",
  "Если такой аккаунт существует, код уже отправлен на email.": "Si esa cuenta existe, el código ya se ha enviado por correo.",
