  "Метод придумал врач Эдмунд Джейкобсон в 1920-х. В исследованиях он снижает тревогу и давление и даёт заметный эффект уже после первого занятия.": "El método lo ideó el médico Edmund Jacobson en los años 20. En los estudios reduce la ansiedad y la tensión arterial y tiene un efecto notable desde la primera sesión.",
