  "Нужно обновить приложение": "Hay que actualizar la app",
  "Нужны имя, дата и город рождения. Время, если знаешь.": "Hacen falta nombre, fecha y ciudad de nacimiento. La hora, si la sabes.",
  "О чём лучше сказать сразу": "Qué conviene decir enseguida",
  "ОКТ": "OCT",
  "Оба живут чувствами и заботой. Тепло вместе, важно только не утонуть в эмоциях вдвоём.": "Ambos vivís de sentimientos y cuidados. Juntos hay calidez, solo no os ahoguéis en las emociones.",
  "Оба надёжные и практичные. Вместе хорошо строить планы, дом и общее дело.": "Ambos sois fiables y prácticos. Juntos es fácil construir planes, un hogar y un proyecto común.",
  "Оба ценят свободу и своё мнение. Интересно вместе, если не давить друг на друга.": "Ambos valoráis la libertad y vuestra opinión. Juntos es interesante si no os presionáis.",
  "Обнови резюме и скажи знакомым, что открыт к предложениям. Решение принимай, когда предложение будет на руках, а не заранее.": "Actualiza tu currículum y di a tus contactos que estás abierto a ofertas. Decide cuando tengas la oferta en la mano, no antes.",
  "Обновить": "Actualizar",
  "Обратная связь": "Comentarios",
  "Объект в небе → точка на карте": "Un objeto en el cielo → un punto en la carta",
  "Обычный вопрос, понятный ответ. Ниже пример того, как можно читать свою карту.": "Una pregunta normal, una respuesta clara. Abajo tienes un ejemplo de cómo puedes leer tu carta.",
  "Обычный день, без особых советов": "Un día normal, sin consejos especiales",
  "Обычный день, без резких поворотов": "Un día normal, sin giros bruscos",
  "Овен": "Aries",
  "Овне": "Aries",
  "Огонь": "Fuego",
  "Один думает, другой чувствует. Интересно вместе, но сказанное не всегда понимается одинаково.": "Uno piensa y el otro siente. Juntos es interesante, pero lo dicho no siempre se entiende igual.",
  "Один из двенадцати участков круга. Здесь видно, какие точки твоей карты в нём стоят.": "Una de las doce partes del círculo. Aquí se ve qué puntos de tu carta están en ella.",
  "Один ищет свободу, другой порядок. Получается, если договориться о правилах.": "Uno busca libertad y el otro orden. Funciona si os ponéis de acuerdo en las reglas.",
  "Один расклад в неделю бесплатно. В Plus расклады без ограничений.": "Una tirada a la semana es gratis. En Plus las tiradas no tienen límite.",
  "Один расклад в неделю бесплатный, и на этой неделе он уже твой. Можно открыть ещё один расклад или все сразу с NEBO Plus.": "Una tirada a la semana es gratis y la de esta semana ya es tuya. Puedes abrir otra tirada o todas a la vez con NEBO Plus.",
  "Один расклад за 99 ₽": "Una tirada por 99 ₽",
  "Один строит, другой согревает. Хорошо для дома и семьи, если ценить вклад друг друга.": "Uno construye y el otro da calor. Bueno para el hogar y la familia si valoráis lo que aporta cada uno.",
  "Одна карта для быстрого ответа, три для ситуации.": "Una carta para una respuesta rápida, tres para una situación.",
  "Одна карта и совет на сегодня": "Una carta y un consejo para hoy",
  "Одна руна и совет на сегодня": "Una runa y un consejo para hoy",
  "Одно уведомление утром. В особые дни, например в твой день рождения или в полнолуние, может прийти ещё одно.": "Un aviso por la mañana. En días especiales, como tu cumpleaños o la luna llena, puede llegar otro.",
  "Одно число": "Mismo número",
  "Окружён системой колец": "Rodeado de un sistema de anillos",
  "Октябрь": "Octubre",
  "Они нужны, чтобы точно посчитать твою натальную карту.": "Hacen falta para calcular bien tu carta natal.",
  "Оплата ещё обрабатывается в RuStore. Дождись результата или нажми «Восстановить покупку».": "El pago aún se está procesando en RuStore. Espera el resultado o toca «Restaurar compra».",
  "Оплата ещё проверяется. Как только RuStore её подтвердит, покупка появится здесь сама.": "El pago aún se está comprobando. En cuanto RuStore lo confirme, la compra aparecerá aquí sola.",
  "Оплата ещё проверяется. Расклад появится здесь, как только RuStore её подтвердит.": "El pago aún se está comprobando. La tirada aparecerá aquí en cuanto RuStore lo confirme.",
  "Оплата завершена, но сервер ещё подтверждает Premium. Новый счёт не откроется, проверь статус этой же кнопкой.": "El pago se ha hecho, pero el servidor aún está confirmando Premium. No se abrirá otra factura, comprueba el estado con este mismo botón.",
