  "По буквам имени считаются число души, образа и таланта. Это открывается с NEBO Plus или с «Эзотерикой на год».": "Los números del alma, la imagen y el talento se calculan con las letras del nombre. Se abre con NEBO Plus o con «Esoterismo durante un año».",
  "По возрастам: три этапа жизни": "Por edades: tres etapas de la vida",
  "По дням открыт ближайший месяц. Этот день войдёт в него ближе к дате, а пока смотри главное месяца ниже.": "El próximo mes está abierto por días. Este día se sumará más cerca de la fecha; por ahora mira abajo lo principal del mes.",
