  "Под стрессом мы незаметно зажимаем плечи, челюсть, живот. Если сначала сильно напрячь мышцу, а потом отпустить, она расслабляется глубже, чем от команды «расслабься». Заодно учишься замечать, где копится напряжение.": "Con estrés apretamos sin darnos cuenta los hombros, la mandíbula y el abdomen. Si primero tensas fuerte un músculo y luego lo sueltas, se relaja más que con la orden «relájate». Además aprendes a notar dónde se acumula la tensión.",
