  "Показываем то, что уже сохранено. Новое подтянется само, когда появится сеть. Если включён VPN, попробуй выключить его: с ним NEBO иногда не загружается.": "Mostramos lo que ya está guardado. Lo nuevo llegará solo cuando vuelva la red. Si tienes VPN, prueba a apagarla: con ella NEBO a veces no carga.",
