  "После оплаты появится код. Отправь его другу в любом мессенджере: он введёт код в NEBO, и Plus откроется у него.": "Tras el pago aparece un código. Envíalo por cualquier mensajería: esa persona lo introduce en NEBO y se le abre Plus.",
