  "Растущий серп": "Creciente",
  "Расчёт карты может занять до 1 минуты. Это время нужно для точного расчёта положений планет на момент вашего рождения.": "El cálculo de la carta puede tardar hasta 1 minuto. Hace falta para calcular con precisión las posiciones de los planetas en el momento de tu nacimiento.",
  "Расчёт натальной карты": "Cálculo de la carta natal",
  "Расчёт по тем же эфемеридам, что у астрологов": "Cálculo con las mismas efemérides que usan los astrólogos",
  "Расчёт профессиональный, методики классические. Любую карту можно сверить с другими сервисами.": "El cálculo es profesional y los métodos, clásicos. Puedes comparar cualquier carta con otros servicios.",
  "Расчёт связи": "Cálculo del aspecto",
  "Расчёт точки": "Cálculo del punto",
  "Реальные небесные тела и их положения на круговой схеме": "Cuerpos celestes reales y sus posiciones en un esquema circular",
  "Реальный объект, не расчётная точка": "Un objeto real, no un punto calculado",
  "Результат будет, но не сразу. То, что начнётся этой осенью, принесёт плоды к весне.": "Habrá resultado, pero no de inmediato. Lo que empiece este otoño dará fruto en primavera.",
  "Ремонт": "Reforma",
  "Ретроградный Меркурий": "Mercurio retrógrado",
  "Ретроградный Меркурий: несколько недель кажется, что Меркурий идёт по небу назад. Меркурий отвечает за разговоры, переписку, договоры и поездки, поэтому в эти дни люди чаще путаются в словах, сроках и билетах.": "Mercurio retrógrado: durante unas semanas parece que Mercurio retrocede por el cielo. Mercurio se encarga de las conversaciones, los mensajes, los contratos y los viajes, así que estos días la gente confunde más a menudo palabras, plazos y billetes.",
  "Ровная неделя без резких поворотов": "Una semana estable, sin giros bruscos",
  "Рост, удача, расширение горизонтов": "Crecimiento, suerte, horizontes más amplios",
  "Руна": "Runa",
  "Руна дня": "Runa del día",
  "Руна дня и расклад из трёх рун на твой вопрос": "La runa del día y una tirada de tres runas para tu pregunta",
  "Руны": "Runas",
  "Руны не советуют уходить резко. Старое терпение закончилось, новый путь уже начат, и он окупится, если дать ему время.": "Las runas no aconsejan irse de golpe. La vieja paciencia se ha acabado, el camino nuevo ya ha empezado y dará frutos si le das tiempo.",
