  "Солнце всегда освещает половину Луны. С Земли мы видим эту половину под разными углами.": "El Sol siempre ilumina la mitad de la Luna. Desde la Tierra vemos esa mitad desde distintos ángulos.",
  "Солнце и Луна": "Sol y Luna",
  "Солнце с видимой светящейся поверхностью и протуберанцами": "El Sol con su superficie luminosa visible y protuberancias",
  "Солнце, Луна и планеты различаются физически, но на карте их показывают как рассчитанные положения.": "El Sol, la Luna y los planetas son físicamente distintos, pero en la carta se muestran como posiciones calculadas.",
