  "Стало сильнее. Это бывает, попробуй «Здесь и сейчас».": "Ha aumentado. A veces pasa, prueba «Aquí y ahora».",
  "Стеллиумы и конфигурации описывают группы положений, а не отдельную новую планету.": "Los stelliums y las configuraciones describen grupos de posiciones, no un planeta nuevo aparte.",
  "Стоит ли мне менять работу этой осенью?": "¿Debería cambiar de trabajo este otoño?",
  "Стоп": "Parar",
  "Стрелец": "Sagitario",
  "Стрельце": "Sagitario",
  "Стресс бывает разный, и помогает разное. Если накрыло прямо сейчас, нажми красную кнопку. Если хочешь разобраться, выбери состояние. Если хочешь стать устойчивее, делай по 2–5 минут в день и веди дневник.": "El estrés es distinto cada vez y ayudan cosas distintas. Si te ha golpeado ahora mismo, toca el botón rojo. Si quieres entenderlo, elige un estado. Si quieres ganar estabilidad, dedica 2–5 minutos al día y lleva un diario.",
  "Стресс кажется «просто плохим днём», пока не видишь его по дням. Отмечай уровень и причину за 10 секунд. Через неделю станет видно, что тебя выбивает и в какие дни, и под это можно подбирать технику.": "El estrés parece «solo un mal día» hasta que lo ves por días. Marca el nivel y el motivo en 10 segundos. En una semana verás qué te descoloca y qué días, y podrás elegir una técnica para eso.",
  "Стрижка и уход": "Corte de pelo y cuidados",
