  "Точки": "Puntos",
  "Транзиты, прогрессии и возвращения используют разные правила расчёта. Это методы, а не готовые предсказания.": "Los tránsitos, las progresiones y los retornos usan reglas de cálculo distintas. Son métodos, no predicciones hechas.",
  "Тревожный мозг живёт в «а вдруг» и «что будет». Когда ты ищешь глазами, ушами и руками реальные вещи вокруг, внимание возвращается в сейчас, и накрутка слабеет.": "Un cerebro ansioso vive en el «y si» y el «qué pasará». Cuando buscas cosas reales a tu alrededor con los ojos, los oídos y las manos, la atención vuelve al ahora y la rumiación se debilita.",
  "Три карты покажут, что было, что есть и к чему идёт.": "Tres cartas muestran qué hubo, qué hay y hacia dónde va.",
  "Три руны покажут, что было, что есть и к чему идёт.": "Tres runas muestran qué hubo, qué hay y hacia dónde va.",
