  "Ты": "Tú",
  "Ты {0} по году рождения: что это значит и чего ждать от 2026": "Eres {0} por tu año de nacimiento: qué significa y qué esperar de 2026",
  "Ты вышел с этого устройства. Войди снова, чтобы вернуть карту, историю и Premium.": "Has cerrado sesión en este dispositivo. Vuelve a entrar para recuperar tu carta, tu historial y Premium.",
  "Ты долго держался на терпении и не позволял себе уйти, пока всё не будет сделано как надо. Это вытянуло работу, но и вымотало.": "Has aguantado mucho a base de paciencia y no te permitías irte hasta que todo estuviera bien hecho. Eso sacó adelante el trabajo, pero te ha agotado.",
