  "Цифры твоей даты рождения разложены по клеткам. Чем больше одинаковых цифр, тем ярче эта черта. «Нет» значит, что здесь полагаться лучше на план, а не на удачу.": "Las cifras de tu fecha de nacimiento se reparten en casillas. Cuantas más cifras iguales, más marcado el rasgo. «No hay» significa que aquí conviene confiar en un plan y no en la suerte.",
  "ЧТ": "JUE",
  "Чаще всего выбивало:": "Lo que más te descolocó:",
  "Чем ближе угол к указанному числу, тем точнее аспект. Допуск называют орбисом.": "Cuanto más se acerca el ángulo a ese número, más exacto es el aspecto. El margen se llama orbe.",
