  "Четыре опорные точки карты": "Los cuatro puntos de apoyo de la carta",
  "Числа": "Números",
  "Числа делятся на три семьи: 1, 5, 7 про свободу и ум, 2, 4, 8 про дело и порядок, 3, 6, 9 про чувства и заботу. Внутри семьи легко, а между семьями люди дополняют друг друга.": "Los números forman tres familias: 1, 5, 7 van de libertad y mente; 2, 4, 8 de trabajo y orden; 3, 6, 9 de sentimientos y cuidado. Dentro de una familia es fácil, y entre familias las personas se complementan.",
  "Числа считаются по дате рождения и по имени. Без даты считать нечего.": "Los números se calculan con la fecha de nacimiento y el nombre. Sin fecha no hay nada que calcular.",
