  "Чтобы ввести код, войди в аккаунт.": "Inicia sesión para introducir un código.",
  "Чтобы покупка не потерялась, сначала привяжи вход через Яндекс, VK или почту в профиле.": "Para que la compra no se pierda, vincula antes el acceso con Yandex, VK o correo en tu perfil.",
  "Чтобы сравнить пару, укажи свою дату рождения в профиле.": "Para comparar una pareja, indica tu fecha de nacimiento en el perfil.",
  "Чёрные": "Negros",
  "Шаг {0} из {1}": "Paso {0} de {1}",
  "Шестизначный код из письма": "El código de seis dígitos del correo",
  "Эзотерика": "Esoterismo",
  "Эзотерика открыта": "El esoterismo está abierto",
  "Эклиптический круг делят на 12 равных знаков по 30°.": "El círculo de la eclíptica se divide en 12 signos iguales de 30°.",
  "Экран не открылся из-за ошибки. Мы уже получили отчёт. Попробуй перезагрузить приложение.": "La pantalla no se abrió por un error. Ya hemos recibido el informe. Prueba a recargar la app.",
  "Эмоции острее обычного": "Emociones más intensas de lo normal",
  "Эмоции, привычный отклик, то, что замечаешь только для себя": "Emociones, tu reacción habitual, lo que notas solo para ti",
  "Это два конца одной оси карты, между ними всегда 180°. Так устроена любая карта, а о характере говорят сами эти точки и их связи с планетами.": "Son los dos extremos de un eje de la carta, siempre a 180°. Así es toda carta, y del carácter hablan estos puntos y sus vínculos con los planetas.",
  "Это день {0}. {1}": "Es un día de {0}. {1}",
  "Это народные лунные традиции, а не наука. Для интереса и в помощь выбору, но не вместо врача, садовода или здравого смысла.": "Son tradiciones lunares populares, no ciencia. Por curiosidad y para ayudarte a elegir, no en lugar de un médico, un jardinero o el sentido común.",
  "Это общие советы, не диета и не лечение.": "Son consejos generales, no una dieta ni un tratamiento.",
  "Это пример расклада": "Esto es un ejemplo de tirada",
  "Это приёмы самопомощи, не лечение. Если тревога держится неделями или бывают приступы паники, обратись к врачу или психологу.": "Son técnicas de autoayuda, no un tratamiento. Si la ansiedad dura semanas o tienes ataques de pánico, acude a un médico o psicólogo.",
  "Это продолжение того же рассказа, а не другой текст": "Esto continúa la misma historia, no es otro texto",
  "Это связь двух точек под углом {0}°. {1}": "Es un vínculo entre dos puntos en un ángulo de {0}°. {1}",
  "Это связь двух точек под углом {0}°. {1}Смысл зависит от того, какие точки она соединяет.": "Es un vínculo entre dos puntos en un ángulo de {0}°. {1}Su sentido depende de qué puntos une.",
  "Это твой день": "Este es tu día",
  "Это три твоих личных числа: года, месяца и дня. Их считают по дате рождения и сегодняшней дате, поэтому они меняются. Каждое подсказывает, на что сейчас лучше потратить силы.": "Son tus tres números personales: del año, del mes y del día. Se calculan con tu fecha de nacimiento y la de hoy, por eso cambian. Cada uno sugiere en qué conviene gastar energía ahora.",
  "Это ты в NEBO": "Este eres tú en NEBO",
  "Этот аккаунт заблокирован. Войди в другой аккаунт или обратись в поддержку.": "Esta cuenta está bloqueada. Entra en otra cuenta o contacta con soporte.",
  "Этот код уже использовали все, кому он был выдан.": "Este código ya lo ha usado todo el mundo a quien se le dio.",
  "Этот код уже использован.": "Este código ya se ha usado.",
  "Этот способ входа пока не настроен. Выбери другой.": "Este método de acceso aún no está configurado. Elige otro.",
  "Этот способ входа уже принадлежит другому аккаунту. Войди в тот аккаунт, данные автоматически не объединяются.": "Este método de acceso ya pertenece a otra cuenta. Entra en esa cuenta, los datos no se unen automáticamente.",
  "Эфемериды дают положения объектов, а время и место задают систему отсчёта.": "Las efemérides dan las posiciones de los objetos, y la hora y el lugar fijan el sistema de referencia.",
